import csv
# load
ings=[]
with open('/root/ingredient_cost.csv') as f:
    for row in csv.DictReader(f): ings.append(row)
cards={int(r['blister_card_count']):float(r['card_cost_usd']) for r in csv.DictReader(open('/root/card_cost.csv'))}
reim={r['medication']:float(r['reimbursement_per_cycle_180_patients_usd']) for r in csv.DictReader(open('/root/reimbursement.csv'))}
patients=180; fills28=12; fills56=6; caps28=56; caps56=112
for mode in ['same_card_cost_per_fill','double_56_packaging','card_count_mult_caps?']:
 total28=total56=0
 for row in ings:
  med=row['medication']; p=float(row['price_per_1000_capsules_usd']); bc=int(row['blister_card_count']); cc=cards[bc]
  annual_drug28=round((caps28/1000)*p*patients*fills28,2)
  annual_drug56=round((caps56/1000)*p*patients*fills56,2)
  annual_pkg28=round(cc*patients*fills28,2)
  if mode=='same_card_cost_per_fill': annual_pkg56=round(cc*patients*fills56,2)
  elif mode=='double_56_packaging': annual_pkg56=round(cc*2*patients*fills56,2)
  else: annual_pkg56=round(cc*bc*patients*fills56,2)
  annual_reimb28=round(reim[med]*fills28,2); annual_reimb56=round(reim[med]*fills56,2)
  total28+=round(annual_reimb28-annual_drug28-annual_pkg28,2)
  total56+=round(annual_reimb56-annual_drug56-annual_pkg56,2)
 print(mode, round(total28,2), round(total56,2), round(total56-total28,2), abs(round(total56-total28,2)))
